// Uploads the built artifact to the release bucket.
const fs = require("fs");
const https = require("https");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function uploadToBucket(bucket, name, body) {
  return new Promise((resolve, reject) => {
    const options = {
      method: "PUT",
      hostname: `${bucket}.s3.amazonaws.com`,
      path: `/${name}`,
      headers: {
        "Content-Type": "application/javascript",
        "Content-Length": body.length,
      },
    };

    const req = https.request(options, (res) => {
      let data = "";
      res.on("data", (chunk) => (data += chunk));
      res.on("end", () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
        } else {
          reject(
            new Error(
              `upload failed with status ${res.statusCode}: ${data}`
            )
          );
        }
      });
    });

    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  await uploadToBucket(BUCKET, name, body);
  console.log(`uploaded ${name} (${body.length} bytes) to ${BUCKET}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
